-- SB-24: chore types, points, frequency and due time; chore stages; and
-- per-period chore instances with stage progress. See "Recurrence" in
-- ../README.md for why each period is its own chore_instances row.
-- Generated by drizzle-kit; hand edits: this header, the chores unique
-- constraint moved before the FKs that need it, and the grants at the end.
-- Existing chores become personal, daily, 10-point chores.

CREATE TYPE "public"."chore_frequency" AS ENUM('daily', 'weekly', 'weekends');--> statement-breakpoint
CREATE TYPE "public"."chore_type" AS ENUM('personal', 'rotation');--> statement-breakpoint
CREATE TABLE "chore_instances" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"household_id" uuid NOT NULL,
	"chore_id" uuid NOT NULL,
	"period_start" date NOT NULL,
	"assigned_member_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chore_instances_chore_id_period_start_key" UNIQUE("chore_id","period_start"),
	CONSTRAINT "chore_instances_id_chore_id_key" UNIQUE("id","chore_id")
);
--> statement-breakpoint
ALTER TABLE "chore_instances" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "chore_stage_progress" (
	"instance_id" uuid NOT NULL,
	"stage_id" uuid NOT NULL,
	"chore_id" uuid NOT NULL,
	"household_id" uuid NOT NULL,
	"completed_by_member_id" uuid,
	"completed_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chore_stage_progress_pkey" PRIMARY KEY("instance_id","stage_id")
);
--> statement-breakpoint
ALTER TABLE "chore_stage_progress" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "chore_stages" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"household_id" uuid NOT NULL,
	"chore_id" uuid NOT NULL,
	"position" smallint NOT NULL,
	"title" text NOT NULL,
	"hint" text,
	"points" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chore_stages_chore_id_position_key" UNIQUE("chore_id","position"),
	CONSTRAINT "chore_stages_id_chore_id_key" UNIQUE("id","chore_id"),
	CONSTRAINT "chore_stages_position_check" CHECK ("chore_stages"."position" >= 1),
	CONSTRAINT "chore_stages_title_check" CHECK (char_length(btrim("chore_stages"."title")) between 1 and 100),
	CONSTRAINT "chore_stages_hint_check" CHECK ("chore_stages"."hint" is null or char_length("chore_stages"."hint") <= 500),
	CONSTRAINT "chore_stages_points_check" CHECK ("chore_stages"."points" >= 0)
);
--> statement-breakpoint
ALTER TABLE "chore_stages" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "chores" ADD COLUMN "type" "chore_type" DEFAULT 'personal' NOT NULL;--> statement-breakpoint
ALTER TABLE "chores" ADD COLUMN "points" integer DEFAULT 10 NOT NULL;--> statement-breakpoint
ALTER TABLE "chores" ADD COLUMN "frequency" "chore_frequency" DEFAULT 'daily' NOT NULL;--> statement-breakpoint
ALTER TABLE "chores" ADD COLUMN "due_time" time;--> statement-breakpoint
ALTER TABLE "chores" ADD COLUMN "due_label" text;--> statement-breakpoint
