CREATE POLICY "chore_instances_select" ON "chore_instances" AS PERMISSIVE FOR SELECT TO "authenticated_backend" USING (app.is_household_member("chore_instances"."household_id"));--> statement-breakpoint
CREATE POLICY "chore_instances_insert" ON "chore_instances" AS PERMISSIVE FOR INSERT TO "authenticated_backend" WITH CHECK (app.is_household_member("chore_instances"."household_id")
				and ("chore_instances"."assigned_member_id" is null or app.is_member_id_in("chore_instances"."household_id", "chore_instances"."assigned_member_id")));--> statement-breakpoint
CREATE POLICY "chore_instances_update" ON "chore_instances" AS PERMISSIVE FOR UPDATE TO "authenticated_backend" USING (app.is_household_parent("chore_instances"."household_id")) WITH CHECK (app.is_household_parent("chore_instances"."household_id")
				and ("chore_instances"."assigned_member_id" is null or app.is_member_id_in("chore_instances"."household_id", "chore_instances"."assigned_member_id")));--> statement-breakpoint
CREATE POLICY "chore_instances_delete" ON "chore_instances" AS PERMISSIVE FOR DELETE TO "authenticated_backend" USING (app.is_household_parent("chore_instances"."household_id"));--> statement-breakpoint
CREATE POLICY "chore_stage_progress_select" ON "chore_stage_progress" AS PERMISSIVE FOR SELECT TO "authenticated_backend" USING (app.is_household_member("chore_stage_progress"."household_id"));--> statement-breakpoint
CREATE POLICY "chore_stage_progress_insert" ON "chore_stage_progress" AS PERMISSIVE FOR INSERT TO "authenticated_backend" WITH CHECK (app.is_household_member("chore_stage_progress"."household_id")
				and app.is_member_id_in("chore_stage_progress"."household_id", "chore_stage_progress"."completed_by_member_id")
				and (app.is_household_parent("chore_stage_progress"."household_id") or app.can_act_as_member("chore_stage_progress"."completed_by_member_id")));--> statement-breakpoint
CREATE POLICY "chore_stage_progress_delete" ON "chore_stage_progress" AS PERMISSIVE FOR DELETE TO "authenticated_backend" USING (app.is_household_parent("chore_stage_progress"."household_id")
				or app.can_act_as_member("chore_stage_progress"."completed_by_member_id"));--> statement-breakpoint
CREATE POLICY "chore_stages_select" ON "chore_stages" AS PERMISSIVE FOR SELECT TO "authenticated_backend" USING (app.is_household_member("chore_stages"."household_id"));--> statement-breakpoint
CREATE POLICY "chore_stages_insert" ON "chore_stages" AS PERMISSIVE FOR INSERT TO "authenticated_backend" WITH CHECK (app.is_household_parent("chore_stages"."household_id"));--> statement-breakpoint
CREATE POLICY "chore_stages_update" ON "chore_stages" AS PERMISSIVE FOR UPDATE TO "authenticated_backend" USING (app.is_household_parent("chore_stages"."household_id")) WITH CHECK (app.is_household_parent("chore_stages"."household_id"));--> statement-breakpoint
CREATE POLICY "chore_stages_delete" ON "chore_stages" AS PERMISSIVE FOR DELETE TO "authenticated_backend" USING (app.is_household_parent("chore_stages"."household_id"));--> statement-breakpoint

-- The default privileges from 0002 already cover these new tables; this keeps
